6	/**
7	 * Cookie that puts the mock-auth layer into admin mode (see
8	 * `getMockAuthState` in `src/lib/auth.server.ts`). The target server must be
9	 * running with `PLAYWRIGHT_TEST=true` (set by `npm run start:ci`) for it to
10	 * be honoured — in production the cookie is ignored.
11	 */
12	const ADMIN_COOKIE = 'mock-auth-state=admin';
13	
14	/** Default report location, matching the v1 linkinator CLI output path. */
15	const DEFAULT_REPORT_PATH = 'linkinator-report.json';
16	
17	/** The subset of `linkinator.config.json` this crawl reuses. */
18	interface LinkinatorFileConfig {
19	    recurse?: boolean;
20	    skip?: string[];
21	    retry?: boolean;
22	    concurrency?: number;
23	    timeout?: number;
24	}
25	
26	/**
27	 * Reads the shared crawl settings from `linkinator.config.json` so the
28	 * authenticated crawl uses the same skip list, retry policy and concurrency
29	 * as the v1 CLI crawl — one source of truth for both.
30	 *
31	 * @param path - Path to the config file.
32	 * @returns The parsed config.
33	 */
34	export function readLinkinatorConfig(
35	    path = 'linkinator.config.json',
36	): LinkinatorFileConfig {
37	    return JSON.parse(readFileSync(path, 'utf8')) as LinkinatorFileConfig;
38	}
39	
40	/** Options for {@link runLinkCheck}. */
41	export interface RunLinkCheckOptions {
42	    /** Origin to crawl. Defaults to `SITE_URL`, then `http://127.0.0.1:3000`. */
43	    baseUrl?: string;
44	    /** Path to `linkinator.config.json`. */
45	    configPath?: string;
46	    /** Where to write the JSON report. */
47	    reportPath?: string;
48	}
49	
50	/** Origin to crawl: explicit arg, else `SITE_URL`, else the local CI server. */
51	function resolveBaseUrl(explicit?: string): string {
52	    const trimmed = (explicit ?? process.env.SITE_URL ?? '')
53	        .trim()
54	        .replace(/\/+$/, '');
55	    return trimmed.length > 0 ? trimmed : 'http://127.0.0.1:3000';
56	}
